import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const c=JSON.parse('{"title":"Web 安全","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/Web安全.md","filePath":"安全方向/Web安全.md","lastUpdated":1792430298000}'),i={name:"安全方向/Web安全.md"};function o(d,t,h,n,b,s){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="web-安全" tabindex="-1">Web 安全 <a class="header-anchor" href="#web-安全" aria-label="Permalink to &quot;Web 安全&quot;">​</a></h1><blockquote><p>互联网世界最普遍的攻击面，也是 CTF 与就业市场需求最大的方向。校内相关课程为「Web 应用安全」（方向课，黄日茂老师曾开设）。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>Web 应用无处不在，OWASP Top 10 长期是安全行业的核心清单；</li><li>Web 安全入门门槛相对友好（不需要先啃汇编），适合作为攻防方向的起点；</li><li>渗透测试、安全研发、安全测试岗位的核心需求。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/程序设计基础.html">程序设计基础</a>（能读懂 HTTP 与前后端代码）</li><li><a href="./../专业基础/计算机网络.html">计算机网络</a>（HTTP 协议细节）</li><li><a href="./../专业基础/数据库.html">数据库</a>（SQL 注入的地基）</li><li><a href="./../必学工具/BurpSuite与Web调试.html">Burp Suite 与 Web 调试</a></li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>HTTP 协议：请求/响应、Cookie/Session、同源策略</li><li>注入类：SQL 注入、命令注入</li><li>XSS（反射/存储/DOM）与 CSRF</li><li>文件上传与文件包含（LFI/RFI）</li><li>SSRF、XXE、反序列化</li><li>越权（水平/垂直）、逻辑漏洞</li><li>防护视角：输入校验、输出编码、安全头、WAF 概念</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《白帽子讲 Web 安全》（吴翰清）</td><td>书</td><td>中文 Web 安全圣经级入门</td></tr><tr><td>《Web 安全深度剖析》</td><td>书</td><td>漏洞原理与实践结合</td></tr><tr><td><a href="https://portswigger.net/web-security" target="_blank" rel="noreferrer">PortSwigger Web Security Academy</a></td><td>在线课程</td><td>官方免费，含实验环境，强烈推荐</td></tr><tr><td><a href="https://owasp.org/www-project-top-ten/" target="_blank" rel="noreferrer">OWASP Top 10</a></td><td>文档</td><td>权威漏洞清单</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>原理 + 靶场</strong>并行：每个漏洞先在 DVWA / pikachu / WebGoat 上复现，再看理论；</li><li>用好 Burp Suite（Repeater + Intruder），练到「闭眼改包」；</li><li>CTF Web 题是很好的进阶练习（题目短、知识点集中）；</li><li>关注 OWASP Top 10 每年的更新，保持知识不落后。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>Web 应用安全（方向课）</li><li>网络攻防技术（第 6 学期，核心课）中的 Web 攻击模块</li></ul>',14)])])}const p=e(i,[["render",o]]);export{c as __pageData,p as default};
